begin;
select no_plan();
set local role authenticated;
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000001',true);
select set_config('test.private',public.create_conversation('00000000-0000-4000-8000-000000000101','Original private synthetic chat','private')::text,true);
select set_config('test.shared',public.create_conversation('00000000-0000-4000-8000-000000000101','Original shared synthetic chat','shared')::text,true);
select public.ask_fixture_gros('00000000-0000-4000-8000-000000000101',current_setting('test.private')::uuid,'00000000-0000-4000-8000-000000000601','Why is this campaign here?','explain','');
select is((select count(*) from public.chat_messages),2::bigint,'GROS explanation and question persist');
select ok((select body like '%Next step:%' and body not like '%{%' from public.chat_messages where role='assistant'),'explanation is plain language with a next step and no raw JSON');
select set_config('test.proposal',public.ask_fixture_gros('00000000-0000-4000-8000-000000000101',current_setting('test.shared')::uuid,'00000000-0000-4000-8000-000000000601','Clarify the goal.','edit_goal','A new original synthetic education goal')::text,true);
select set_config('test.hash',(select payload_hash from public.chat_proposals where id=current_setting('test.proposal')::uuid),true);
select isnt((select goal from public.campaigns where id='00000000-0000-4000-8000-000000000601'),'A new original synthetic education goal','proposal does not mutate campaign before confirmation');
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000005',true);
select is((select count(*) from public.conversations),1::bigint,'staff sees shared conversation, never owner-private chat');
select is((select count(*) from public.chat_messages),2::bigint,'shared member cannot enumerate private messages');
select throws_ok($$select public.ask_fixture_gros('00000000-0000-4000-8000-000000000101',current_setting('test.private')::uuid,'00000000-0000-4000-8000-000000000601','Read private','explain','')$$,'42501',null,'private RPC is creator scoped');
select throws_ok($$select public.decide_chat_proposal('00000000-0000-4000-8000-000000000101',current_setting('test.proposal')::uuid,current_setting('test.hash'),'confirmed')$$,'42501',null,'shared visibility cannot execute another actor proposal');
select throws_ok($$select public.ask_fixture_gros('00000000-0000-4000-8000-000000000101',current_setting('test.shared')::uuid,'00000000-0000-4000-8000-000000000601','Schedule','schedule','')$$,'42501',null,'staff chat cannot propose owner delivery action');
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000004',true);
select is((select count(*) from public.conversations),0::bigint,'shared chats do not cross tenants');
select is((select count(*) from public.chat_proposals),0::bigint,'foreign proposals invisible');
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000003',true);
select is((select count(*) from public.conversations),0::bigint,'designer cannot enumerate GROS');
select is((select count(*) from public.package_cycles),0::bigint,'designer cannot see usage/revenue surfaces');
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000001',true);
select throws_ok($$select public.decide_chat_proposal('00000000-0000-4000-8000-000000000101',current_setting('test.proposal')::uuid,repeat('a',64),'confirmed')$$,'PT409',null,'unseen hash rejected');
select lives_ok($$select public.decide_chat_proposal('00000000-0000-4000-8000-000000000101',current_setting('test.proposal')::uuid,current_setting('test.hash'),'confirmed')$$,'creator confirms exact goal edit');
select is((select goal from public.campaigns where id='00000000-0000-4000-8000-000000000601'),'A new original synthetic education goal','confirmed proposal uses domain save');
select is((select calendar_revision from public.campaigns where id='00000000-0000-4000-8000-000000000601'),2,'GROS edit invalidates exact calendar version');
select lives_ok($$select public.decide_chat_proposal('00000000-0000-4000-8000-000000000101',current_setting('test.proposal')::uuid,current_setting('test.hash'),'confirmed')$$,'replayed confirmation is idempotent');
select set_config('test.expired',public.ask_fixture_gros('00000000-0000-4000-8000-000000000101',current_setting('test.shared')::uuid,'00000000-0000-4000-8000-000000000601','Change goal again','edit_goal','Original goal again')::text,true);
select set_config('test.expiredhash',(select payload_hash from public.chat_proposals where id=current_setting('test.expired')::uuid),true);
reset role;
update public.chat_proposals set expires_at=now()-interval '1 second' where id=current_setting('test.expired')::uuid;
set local role authenticated;
select throws_ok($$select public.decide_chat_proposal('00000000-0000-4000-8000-000000000101',current_setting('test.expired')::uuid,current_setting('test.expiredhash'),'confirmed')$$,'PT409',null,'expired proposal requires new confirmation');
select set_config('test.stale',public.ask_fixture_gros('00000000-0000-4000-8000-000000000101',current_setting('test.shared')::uuid,'00000000-0000-4000-8000-000000000601','Change goal','edit_goal','Stale goal')::text,true);
select set_config('test.stalehash',(select payload_hash from public.chat_proposals where id=current_setting('test.stale')::uuid),true);
reset role;
update public.campaigns set delivery_revision=delivery_revision+1 where id='00000000-0000-4000-8000-000000000601';
set local role authenticated;
select throws_ok($$select public.decide_chat_proposal('00000000-0000-4000-8000-000000000101',current_setting('test.stale')::uuid,current_setting('test.stalehash'),'confirmed')$$,'PT409',null,'any changed target revision invalidates unseen proposal');
select public.add_holiday('00000000-0000-4000-8000-000000000101','Original fixture event','2027-01-01','Manual workspace event');
select is((select count(*) from public.holidays),1::bigint,'custom event persists');
select set_config('test.ticket',public.open_support_ticket('00000000-0000-4000-8000-000000000101','feedback','Original fixture feedback','Please inspect the synthetic workflow.')::text,true);
select public.reply_support('00000000-0000-4000-8000-000000000101',current_setting('test.ticket')::uuid,1,'Original fixture follow-up','in_progress');
select is((select count(*) from public.support_messages),2::bigint,'support history persists both messages');
select throws_ok($$select public.reply_support('00000000-0000-4000-8000-000000000101',current_setting('test.ticket')::uuid,1,'Stale','closed')$$,'PT409',null,'support thread has optimistic revisions');
select set_config('test.invite',public.invite_team('00000000-0000-4000-8000-000000000101','other-owner@grey-retention.test','staff')::text,true);
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000004',true);
select is((select count(*) from public.my_pending_invites()),0::bigint,'unverified email cannot claim invitation');
reset role;
update auth.users set email_confirmed_at=now() where id='00000000-0000-4000-8000-000000000004';
set local role authenticated;
select is((select count(*) from public.my_pending_invites()),1::bigint,'verified invited email can see pending invite');
select lives_ok($$select public.accept_team_invite(current_setting('test.invite')::uuid)$$,'verified invited account accepts saved invitation');
select is((select count(*) from public.conversations),1::bigint,'new active staff membership sees shared only');
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000002',true);
select is((select count(*) from public.chat_messages),0::bigint,'operator diagnostics never grant private chat reads');
select ok(public.operator_diagnostics()::text not like '%A new original synthetic education goal%','diagnostics excludes private/user payloads');
select lives_ok($$select public.reply_support('00000000-0000-4000-8000-000000000101',current_setting('test.ticket')::uuid,2,'Operator original response','closed')$$,'operator can resolve intentionally shared support thread');
select set_config('test.package',public.define_fixture_package('Synthetic SQL budget proof',10000,10000)::text,true);
select public.assign_fixture_package('00000000-0000-4000-8000-000000000101',current_setting('test.package')::uuid);
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000001',true);
select set_config('test.reserve',public.reserve_fixture_usage('00000000-0000-4000-8000-000000000101','original-sql-budget-operation','copy',8000)::text,true);
select is(public.reserve_fixture_usage('00000000-0000-4000-8000-000000000101','original-sql-budget-operation','copy',8000)::text,current_setting('test.reserve'),'reservation replay does not double-spend');
select is((select reserved_micro from public.package_cycles where state='active' and tenant_id='00000000-0000-4000-8000-000000000101'),8000::bigint,'budget reserves atomically');
select is((select count(*) from public.budget_alerts),2::bigint,'cycle/day 80 percent soft alerts persist once');
select throws_ok($$select public.reserve_fixture_usage('00000000-0000-4000-8000-000000000101','over-budget','design',2001)$$,'23514',null,'hard stop prevents overspend');
select public.reconcile_fixture_usage('00000000-0000-4000-8000-000000000101',current_setting('test.reserve')::uuid,6000);
select public.reconcile_fixture_usage('00000000-0000-4000-8000-000000000101',current_setting('test.reserve')::uuid,6000);
select is((select used_micro from public.package_cycles where state='active' and tenant_id='00000000-0000-4000-8000-000000000101'),6000::bigint,'actual usage reconciliation is idempotent');
select is((select reserved_micro from public.package_cycles where state='active' and tenant_id='00000000-0000-4000-8000-000000000101'),0::bigint,'actual usage releases unused reservation');
select is((select used_micro from public.fixture_usage_summary('00000000-0000-4000-8000-000000000101') where feature='copy'),6000::bigint,'feature usage aggregates the complete active cycle');
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000005',true);
select throws_ok($$select public.reserve_fixture_usage('00000000-0000-4000-8000-000000000101','staff-budget','copy',1000)$$,'42501',null,'staff cannot manipulate usage ledger directly');
select throws_ok($$select public.define_fixture_package('Unauthorized',10000,10000)$$,'42501',null,'package limits require super admin');
select * from finish();rollback;
